def absolute_gap(a, b):
    if a > b:
        return a - b
    return b - a

def can_pair(left, right, required, tolerance):
    a = 0
    b = 0
    pairs = 0
    while a < len(left) and b < len(right):
        difference = left[a] - right[b]
        if difference < -tolerance:
            a += 1
        elif difference > tolerance:
            b += 1
        else:
            pairs += 1
            a += 1
            b += 1
            if pairs >= required:
                return True
    return False

def minimum_pair_tolerance(left, right, required):
    if required == 0:
        return 0
    if required > len(left) or required > len(right):
        return -1
    low = 0
    high = absolute_gap(left[0], right[len(right) - 1])
    other = absolute_gap(left[len(left) - 1], right[0])
    if other > high:
        high = other
    while low < high:
        middle = (low + high) // 2
        if can_pair(left, right, required, middle):
            high = middle
        else:
            low = middle + 1
    return low
